m_actionList.scriptText:
try {
  java.util.Calendar c = java.util.Calendar.getInstance();
  int h = c.get(java.util.Calendar.HOUR_OF_DAY);
  int d = c.get(java.util.Calendar.DAY_OF_WEEK);
  if (h >= 21) return "<big><b>☀️ Kal subah ka EK kaam</b></big><br><br>Kal ka sirf EK kaam chunein — jo ho jaye to din kamyab.<br><br>Usay abhi naam dein. Subah phone se pehle wohi.";
  if (d == 1) return "<big><b>🪞 Hafte ka aaina</b></big><br><br>1. Is hafte dukan mere baghair kitni chali?<br><br>2. Kaun sa masla dobara aaya — us ki jar kya hai?<br><br>3. Agle hafte kaun sa ek kaam CHHORNA hai?";
  return "<big><b>🌙 Raat ke 3 sawal</b></big><br><br>1. Aaj kaun sa kaam aisa kiya jo SIRF main kar sakta tha?<br><br>2. Aaj kis kaam ne mera waqt khaya jo kisi aur ko dena chahiye tha?<br><br>3. Aaj ghar walon ko main ne kya diya — waqt, ya sirf thakan?";
} catch (Throwable t) {
  return "<big><b>🌙 Raat ke 3 sawal</b></big><br><br>1. Aaj kaun sa kaam aisa kiya jo SIRF main kar sakta tha?<br><br>2. Aaj kis kaam ne mera waqt khaya jo kisi aur ko dena chahiye tha?<br><br>3. Aaj ghar walon ko main ne kya diya — waqt, ya sirf thakan?";
}
